-- Generated by build.py from assessments/*.json. Run schema.sql first. Safe to run again: it replaces the questions.

insert into public.assessments (slug, title, pass_pct, questions) values ('as-balance-of-payments', $q$The Current Account: assessment$q$, 80, $q$[{"id": "q1", "type": "num", "q": "Exports of goods are $900m and imports of goods are $1,200m. What is the balance in goods ($m)? Include the sign.", "ans": -300, "tol": 0, "marks": 1, "topic": "Calculations", "hint": "Include the minus sign if negative.", "ok": "Correct: 900 − 1,200 = −300.", "fb": "Balance = exports − imports = 900 − 1,200 = −300, a deficit. See 'Calculating the balances'.", "model": "-300"}, {"id": "q2", "type": "num", "q": "Exports of services are $160m and imports of services are $100m. What is the services balance ($m)?", "ans": 60, "tol": 0, "marks": 1, "topic": "Calculations", "hint": "Enter a number.", "ok": "Correct: 160 − 100 = +60.", "fb": "Services balance = exports − imports = 160 − 100 = 60, a surplus. See 'Calculating the balances'.", "model": "60"}, {"id": "q3", "type": "num", "q": "Goods and services balance −$240m, primary income +$70m, secondary income +$45m. What is the current account balance ($m)?", "ans": -125, "tol": 0, "marks": 1, "topic": "Calculations", "hint": "Include the minus sign if negative.", "ok": "Correct: −240 + 70 + 45 = −125.", "fb": "Current account = goods and services + primary income + secondary income = −240 + 70 + 45 = −125, a deficit. Keep the sign.", "model": "-125"}, {"id": "q4", "type": "num", "q": "A current account deficit is $50m and GDP is $1,000m. The deficit is what percentage of GDP?", "ans": 5, "tol": 0.05, "marks": 1, "topic": "Calculations", "hint": "Enter a percentage.", "ok": "Correct: 50 ÷ 1,000 = 5%.", "fb": "Percentage of GDP = deficit ÷ GDP × 100 = 5. Always judge the size of a deficit relative to the economy.", "model": "5"}, {"id": "q5", "type": "mcq", "q": "Workers' remittances sent home are recorded in:", "opts": ["Secondary income", "Primary income", "Trade in goods", "Trade in services"], "ans": "0", "marks": 1, "topic": "Components", "ok": "Correct.", "fb": "Transfers with nothing received in exchange, such as aid and remittances, are secondary income. See 'The four parts of the current account'.", "model": "Secondary income"}, {"id": "q6", "type": "mcq", "q": "Profits, interest and dividends from abroad are recorded in:", "opts": ["Primary income", "Secondary income", "Trade in goods", "Trade in services"], "ans": "0", "marks": 1, "topic": "Components", "ok": "Correct.", "fb": "Income from investment and work abroad is primary income. See 'The four parts of the current account'.", "model": "Primary income"}, {"id": "q7", "type": "text", "q": "Complete: exports are recorded in the balance of payments as a ________.", "groups": [["credit", "credits"]], "marks": 1, "topic": "Components", "ok": "Correct: a credit.", "fb": "Money coming in is a credit (+) and money going out is a debit (−). See 'The big idea'.", "model": "Credit.", "hint": "One word."}, {"id": "q8", "type": "mcq", "q": "Which of these is likely to be a CYCLICAL cause of a current account deficit?", "opts": ["A boom at home that raises imports", "An overvalued exchange rate", "Low labour productivity", "Poor education and training"], "ans": "0", "marks": 1, "topic": "Causes", "ok": "Correct.", "fb": "A growing domestic economy raises imports and is short term and often self-correcting. The others are structural. See 'Causes of a current account deficit'.", "model": "A boom at home that raises imports"}, {"id": "q9", "type": "mcq", "q": "Which is likely to be a STRUCTURAL cause of a deficit?", "opts": ["Lack of international competitiveness", "A short-term slowdown among trading partners", "A temporary rise in home spending", "A one-off fall in oil prices"], "ans": "0", "marks": 1, "topic": "Causes", "ok": "Correct.", "fb": "Structural causes are long term and not self-correcting, such as poor competitiveness, an overvalued exchange rate or low productivity. See 'Causes of a current account deficit'.", "model": "Lack of international competitiveness"}, {"id": "q10", "type": "mcq", "q": "A trade deficit means that:", "opts": ["The value of imports is greater than the value of exports", "The quantity of imports is greater than the quantity of exports", "Exports are zero", "The country is in recession"], "ans": "0", "marks": 1, "topic": "Interpreting", "ok": "Correct: value (price × quantity), not quantity.", "fb": "A deficit compares values, not quantities. This is a common exam error. See the 'Do not write this' box.", "model": "The value of imports is greater than the value of exports"}]$q$::jsonb)
on conflict (slug) do update set title = excluded.title, pass_pct = excluded.pass_pct, questions = excluded.questions, updated_at = now();

insert into public.assessments (slug, title, pass_pct, questions) values ('as-comparative-advantage', $q$Comparative Advantage: assessment$q$, 80, $q$[{"id": "q1", "type": "num", "q": "Blue can make at most 40 coats or 160 shirts. How many shirts does Blue give up to make 1 coat?", "ans": 4, "tol": 0, "marks": 1, "topic": "Opportunity cost", "hint": "Enter a number.", "ok": "Correct: 160 ÷ 40 = 4 shirts.", "fb": "Divide what is given up (shirts) by what is gained (coats): 160 ÷ 40 = 4. Revisit Step 2 of the worked example in the Learn tab.", "model": "4"}, {"id": "q2", "type": "num", "q": "Red can make at most 120 coats or 240 shirts. How many coats does Red give up to make 1 shirt? (give a decimal)", "ans": 0.5, "tol": 0.01, "marks": 1, "topic": "Opportunity cost", "hint": "Enter a number.", "ok": "Correct: 120 ÷ 240 = 0.5 coat.", "fb": "The opportunity cost of a shirt is the inverse of the coat calculation: coats given up ÷ shirts gained = 120 ÷ 240 = 0.5. Check Step 2 again.", "model": "0.5"}, {"id": "q3", "type": "mcq", "q": "Using the figures above, which country has the comparative advantage in coats?", "opts": ["Red", "Blue", "Both countries", "Neither country"], "ans": "0", "marks": 1, "topic": "Comparative advantage", "ok": "Correct: Red gives up 2 shirts per coat, Blue gives up 4, so Red's opportunity cost is lower.", "fb": "Compare opportunity costs, not total output. Red gives up 2 shirts per coat and Blue gives up 4, so Red is the lower-cost producer of coats. Re-read the table in Step 2.", "model": "Red"}, {"id": "q4", "type": "text", "q": "Complete the definition: a country has a comparative advantage in a good when it can produce it at a lower ________ than another country.", "groups": [["opportunity cost", "opportunity costs"]], "marks": 1, "topic": "Definitions", "ok": "Correct: lower opportunity cost.", "fb": "The definition is about opportunity cost, not about producing more. A country has a comparative advantage when it gives up fewer other goods to make the good. See the Tips & keywords tab.", "model": "opportunity cost", "hint": "Two words."}, {"id": "q5", "type": "mcq", "q": "A country can make every good using fewer resources than its trading partner. Could it still gain from trade?", "opts": ["Yes, because it is likely to have a lower opportunity cost in some goods", "No, because it has nothing to gain from a weaker country", "Only if the other country has an absolute advantage in something", "Only if it imports every good"], "ans": "0", "marks": 1, "topic": "Absolute vs comparative", "ok": "Correct: the gain comes from comparative, not absolute, advantage.", "fb": "Absolute advantage in everything does not stop trade being worthwhile. Gains come from specialising where the opportunity cost is lower. See 'A country can have an absolute advantage in everything and still gain from trade' in the Learn tab.", "model": "Yes, because it is likely to have a lower opportunity cost in some goods"}, {"id": "q6", "type": "mcq", "q": "In the worked example a coat costs Red 2 shirts and Blue 4 shirts to make. Between which rates of exchange could both countries gain?", "opts": ["Under 2 shirts per coat", "Between 2 and 4 shirts per coat", "Over 4 shirts per coat", "Exactly 3 shirts per coat only"], "ans": "1", "marks": 1, "topic": "Terms of trade", "ok": "Correct: Red wants more than 2 shirts per coat, Blue will pay less than 4.", "fb": "Each side must receive a better deal than making the good itself. Red will not sell a coat for under 2 shirts, and Blue will not pay more than 4. Revisit Step 5.", "model": "Between 2 and 4 shirts per coat"}, {"id": "q7", "type": "num", "q": "Red makes only coats (120) and Blue makes only shirts (160). How many shirts does the world produce?", "ans": 160, "tol": 0, "marks": 1, "topic": "Specialisation", "hint": "Enter a number.", "ok": "Correct: only Blue makes shirts, so the world total is 160.", "fb": "After specialising, only Blue makes shirts, so world shirt output is Blue's maximum of 160. See Step 4.", "model": "160"}, {"id": "q8", "type": "num", "q": "At an exchange rate of 3 shirts per coat, Red sells 40 coats. How many shirts does Red receive?", "ans": 120, "tol": 0, "marks": 1, "topic": "Terms of trade", "hint": "Enter a number.", "ok": "Correct: 40 × 3 = 120 shirts.", "fb": "Shirts received = coats sold × shirts per coat = 40 × 3 = 120. See Step 6.", "model": "120"}, {"id": "q9", "type": "mcq", "q": "Which of these is a limitation of a country specialising heavily according to comparative advantage?", "opts": ["It could become over-dependent on a few exports", "World output tends to fall", "Opportunity costs rise to zero", "Consumers have less choice and higher prices"], "ans": "0", "marks": 1, "topic": "Limitations", "ok": "Correct: over-dependence leaves the country exposed to price falls and shocks.", "fb": "Heavy specialisation can leave a country over-dependent on a few exports, so a fall in world prices or demand may hurt it badly. The other options describe the opposite of the theory's benefits. See the Exam questions tab.", "model": "It could become over-dependent on a few exports"}, {"id": "q10", "type": "text", "q": "What name is given to the rate at which one country's goods exchange for another's?", "groups": [["terms of trade"]], "marks": 1, "topic": "Terms of trade", "ok": "Correct.", "fb": "The term is 'terms of trade'. Add it to your keyword list in the Tips & keywords tab.", "model": "The terms of trade."}]$q$::jsonb)
on conflict (slug) do update set title = excluded.title, pass_pct = excluded.pass_pct, questions = excluded.questions, updated_at = now();

insert into public.assessments (slug, title, pass_pct, questions) values ('as-elasticities-of-demand', $q$Elasticities of Demand: assessment$q$, 80, $q$[{"id": "q1", "type": "num", "q": "Price rises from $10 to $12 and quantity demanded falls from 1,000 to 900. Calculate PED (ignore the sign, give one decimal).", "ans": 0.5, "tol": 0.05, "marks": 1, "topic": "PED calculation", "hint": "Enter a number.", "ok": "Correct: %ΔP = 20%, %ΔQ = 10%, PED = 10 ÷ 20 = 0.5.", "fb": "Use percentage changes on the original value: %ΔP = 2 ÷ 10 = 20%, %ΔQ = 100 ÷ 1,000 = 10%. PED = 10 ÷ 20 = 0.5. Revisit the PED formula in the Learn tab.", "model": "0.5", "abs": true}, {"id": "q2", "type": "num", "q": "Incomes rise by 5% and demand for a good rises by 15%. Calculate YED.", "ans": 3, "tol": 0.01, "marks": 1, "topic": "YED calculation", "hint": "Enter a number.", "ok": "Correct: 15 ÷ 5 = 3.", "fb": "YED = %ΔQd ÷ %ΔY = 15 ÷ 5 = 3. A figure above 1 suggests a luxury or income-elastic good.", "model": "3"}, {"id": "q3", "type": "num", "q": "The price of good B rises by 10% and demand for good A falls by 25%. Calculate XED, including the sign.", "ans": -2.5, "tol": 0.05, "marks": 1, "topic": "XED calculation", "hint": "Include the minus sign if it is negative.", "ok": "Correct: −25 ÷ 10 = −2.5, which suggests complements.", "fb": "XED = %ΔQd of A ÷ %ΔP of B = −25 ÷ 10 = −2.5. Keep the sign for XED, because it shows whether the goods are substitutes or complements.", "model": "-2.5"}, {"id": "q4", "type": "mcq", "q": "A good has a PED of 0.4. If its price rises, what is likely to happen to total revenue?", "opts": ["It rises", "It falls", "It stays the same", "It cannot be known"], "ans": "0", "marks": 1, "topic": "PED and revenue", "ok": "Correct: demand is inelastic, so quantity falls proportionally less than price rises.", "fb": "With PED below 1 (inelastic), the % fall in quantity is smaller than the % rise in price, so revenue tends to rise. See the revenue table in the Learn tab.", "model": "It rises"}, {"id": "q5", "type": "mcq", "q": "A firm cuts the price of a product with PED = 1.8. What is likely to happen to its revenue?", "opts": ["It rises", "It falls", "No change", "It depends on costs"], "ans": "0", "marks": 1, "topic": "PED and revenue", "ok": "Correct: elastic demand means a price cut tends to raise revenue.", "fb": "PED above 1 (elastic): the % rise in quantity is bigger than the % fall in price, so revenue tends to rise. See Lab 1 in the Explore tab.", "model": "It rises"}, {"id": "q6", "type": "mcq", "q": "A negative YED indicates which type of good?", "opts": ["Luxury good", "Normal necessity", "Inferior good", "Complement"], "ans": "2", "marks": 1, "topic": "YED", "ok": "Correct.", "fb": "A negative income elasticity means demand falls as income rises, which is the definition of an inferior good. Examples include own-brand value ranges.", "model": "Inferior good"}, {"id": "q7", "type": "text", "q": "Complete the definition: PED measures the ________ of quantity demanded to a change in a product's own price.", "groups": [["responsiveness", "responsive", "sensitivity", "sensitive"]], "marks": 1, "topic": "Definitions", "ok": "Correct: responsiveness.", "fb": "PED measures how responsive quantity demanded is to a change in the good's own price. See 'Three elasticities of demand' in the Learn tab.", "model": "Responsiveness.", "hint": "One key term."}, {"id": "q8", "type": "mcq", "q": "Which of these is NOT a usual determinant of the price elasticity of demand?", "opts": ["The availability of substitutes", "The proportion of income spent on the good", "The time period considered", "The firm's cost of production"], "ans": "3", "marks": 1, "topic": "Determinants", "ok": "Correct: costs of production affect supply, not PED.", "fb": "PED depends on demand-side factors such as substitutes, the share of income spent and the time period. A firm's costs affect supply. See 'What determines PED?' in the Learn tab.", "model": "The firm's cost of production"}, {"id": "q9", "type": "text", "q": "The XED between butter and margarine is +1.8. What type of relationship does this show?", "groups": [["substitut*"]], "marks": 1, "topic": "XED", "ok": "Correct: a positive XED suggests substitutes.", "fb": "A positive XED means that when the price of one good rises, demand for the other rises too, which is how substitutes behave. Negative would suggest complements.", "model": "Substitutes."}, {"id": "q10", "type": "mcq", "q": "Along a straight-line demand curve, where is demand most price elastic?", "opts": ["At a high price, low quantity", "At the midpoint", "At a low price, high quantity", "PED is the same everywhere"], "ans": "0", "marks": 1, "topic": "PED along a curve", "ok": "Correct: at high prices, small absolute changes are large percentage changes.", "fb": "The slope is constant but PED is not, because it uses percentages. At the top left a small change in quantity is a large percentage change, so demand is more elastic. Watch the animation in the Watch tab.", "model": "At a high price, low quantity"}]$q$::jsonb)
on conflict (slug) do update set title = excluded.title, pass_pct = excluded.pass_pct, questions = excluded.questions, updated_at = now();

insert into public.assessments (slug, title, pass_pct, questions) values ('as-elasticity-of-supply', $q$Price Elasticity of Supply: assessment$q$, 80, $q$[{"id": "q1", "type": "num", "q": "Price rises from $10 to $12 and quantity supplied rises from 100 to 110. Calculate PES.", "ans": 0.5, "tol": 0.05, "marks": 1, "topic": "PES calculation", "hint": "Enter a number.", "ok": "Correct: %ΔQs = 10%, %ΔP = 20%, PES = 0.5.", "fb": "PES = %ΔQs ÷ %ΔP. %ΔQs = 10 ÷ 100 = 10%, %ΔP = 2 ÷ 10 = 20%, so PES = 10 ÷ 20 = 0.5. Check the worked example in the Learn tab.", "model": "0.5"}, {"id": "q2", "type": "num", "q": "Price rises by 20% and quantity supplied rises by 40%. Calculate PES.", "ans": 2, "tol": 0.05, "marks": 1, "topic": "PES calculation", "hint": "Enter a number.", "ok": "Correct: 40 ÷ 20 = 2.", "fb": "PES = %ΔQs ÷ %ΔP = 40 ÷ 20 = 2, so supply is elastic. See the Learn tab.", "model": "2"}, {"id": "q3", "type": "num", "q": "PES is 1.5 and price rises by 8%. By what percentage does quantity supplied rise?", "ans": 12, "tol": 0.1, "marks": 1, "topic": "PES calculation", "hint": "Enter a percentage.", "ok": "Correct: 1.5 × 8 = 12%.", "fb": "Rearrange PES = %ΔQs ÷ %ΔP, so %ΔQs = PES × %ΔP = 1.5 × 8 = 12. See the Learn tab.", "model": "12"}, {"id": "q4", "type": "mcq", "q": "A straight-line supply curve passes through the origin. What is PES along it?", "opts": ["Always 1", "Always 0", "Always greater than 1", "It changes along the line"], "ans": "0", "marks": 1, "topic": "Supply curves", "ok": "Correct: any straight line through the origin has PES = 1 at every point.", "fb": "Slope alone does not decide PES. A straight line through the origin has PES of exactly 1 at every point. See the 'Exam favourite' box in the Learn tab.", "model": "Always 1"}, {"id": "q5", "type": "mcq", "q": "A straight-line supply curve cuts the price (vertical) axis. Supply is:", "opts": ["Elastic (PES above 1)", "Inelastic (PES below 1)", "Unitary", "Perfectly inelastic"], "ans": "0", "marks": 1, "topic": "Supply curves", "ok": "Correct.", "fb": "Cutting the price axis means PES is above 1 (elastic); cutting the quantity axis means PES is below 1 (inelastic). Revisit the Exam favourite box and Lab 2 in the Explore tab.", "model": "Elastic (PES above 1)"}, {"id": "q6", "type": "text", "q": "Complete: in the short run, supply of hotel rooms is ________ because services cannot be stored.", "groups": [["inelastic", "perfectly inelastic", "fixed"]], "marks": 1, "topic": "Determinants", "ok": "Correct: inelastic.", "fb": "Services are perishable and cannot be stored, so supply is fixed or very inelastic in the short run. See 'What determines PES?' in the Learn tab.", "model": "Inelastic.", "hint": "One key term."}, {"id": "q7", "type": "text", "q": "Complete: firms that can build up and run down ________ can meet extra demand quickly, which makes supply more elastic.", "groups": [["stocks", "stock", "inventory", "inventories"]], "marks": 1, "topic": "Determinants", "ok": "Correct: stocks.", "fb": "Held stocks let firms respond to extra demand quickly, so supply is more elastic. See 'What determines PES?' in the Learn tab.", "model": "Stocks.", "hint": "One word."}, {"id": "q8", "type": "mcq", "q": "Which is likely to make supply MORE elastic?", "opts": ["Spare productive capacity", "A shortage of skilled workers", "A shorter time period", "Perishable output"], "ans": "0", "marks": 1, "topic": "Determinants", "ok": "Correct.", "fb": "Spare capacity lets firms raise output easily. Shortages of inputs, short time periods and perishability all make supply less elastic. See the Learn tab.", "model": "Spare productive capacity"}, {"id": "q9", "type": "mcq", "q": "Compared with manufacturing, the supply of agricultural products is usually:", "opts": ["More inelastic", "More elastic", "Perfectly elastic", "The same"], "ans": "0", "marks": 1, "topic": "Agriculture", "ok": "Correct: crops take a growing season and depend on weather.", "fb": "Crops take time to grow, yields depend on weather and switching crops is slow, so agricultural supply tends to be more inelastic. This is why farm prices swing so much. See the Watch tab, step 3.", "model": "More inelastic"}, {"id": "q10", "type": "mcq", "q": "Following an indirect tax, which side of the market tends to bear more of the burden?", "opts": ["The less elastic side", "The more elastic side", "The side with more firms", "Neither"], "ans": "0", "marks": 1, "topic": "Tax incidence", "ok": "Correct.", "fb": "The side that cannot easily change its behaviour (the less elastic side) bears more of the tax. This links to Chapter 13. See the Learn tab.", "model": "The less elastic side"}]$q$::jsonb)
on conflict (slug) do update set title = excluded.title, pass_pct = excluded.pass_pct, questions = excluded.questions, updated_at = now();

insert into public.assessments (slug, title, pass_pct, questions) values ('as-government-intervention', $q$Methods of Government Intervention: assessment$q$, 80, $q$[{"id": "q1", "type": "mcq", "q": "A specific indirect tax shifts the supply curve:", "opts": ["Upwards (to the left) by the amount of the tax", "Downwards (to the right) by the amount of the tax", "Along the demand curve", "Not at all"], "ans": "0", "marks": 1, "topic": "Indirect taxes", "ok": "Correct.", "fb": "A tax raises firms' costs by a fixed amount per unit, so the supply curve shifts up (left) by the amount of the tax. See section 1 in the Learn tab.", "model": "Upwards (to the left) by the amount of the tax"}, {"id": "q2", "type": "num", "q": "A $5 per unit tax is placed on a good and 200 units are sold. How much revenue does the government raise ($)?", "ans": 1000, "tol": 0, "marks": 1, "topic": "Indirect taxes", "hint": "Enter a number.", "ok": "Correct: 5 × 200 = $1,000.", "fb": "Revenue = tax per unit × quantity sold = 5 × 200 = 1,000. See section 1.", "model": "1000"}, {"id": "q3", "type": "mcq", "q": "If demand for a taxed good is inelastic, consumers are likely to:", "opts": ["Bear most of the tax burden", "Bear very little of the burden", "Stop buying the good", "Receive the tax revenue"], "ans": "0", "marks": 1, "topic": "Tax incidence", "ok": "Correct.", "fb": "The less elastic side pays more. Inelastic demand means consumers cannot easily cut back, so they bear most of the burden and the tax barely reduces consumption. See 'Incidence' in section 1.", "model": "Bear most of the tax burden"}, {"id": "q4", "type": "mcq", "q": "What does a per-unit subsidy to producers do to the market?", "opts": ["Lowers the price and raises quantity", "Raises the price and lowers quantity", "Raises both price and quantity", "Lowers both price and quantity"], "ans": "0", "marks": 1, "topic": "Subsidies", "ok": "Correct: supply shifts down (right).", "fb": "A subsidy lowers costs, so supply shifts right: price falls and quantity rises. See section 2.", "model": "Lowers the price and raises quantity"}, {"id": "q5", "type": "num", "q": "The government pays a $3 per unit subsidy and 400 units are sold. What is the cost to the government ($)?", "ans": 1200, "tol": 0, "marks": 1, "topic": "Subsidies", "hint": "Enter a number.", "ok": "Correct: 3 × 400 = $1,200.", "fb": "Cost = subsidy per unit × quantity = 3 × 400 = 1,200. See section 2.", "model": "1200"}, {"id": "q6", "type": "mcq", "q": "For a maximum price to have any effect it must be set:", "opts": ["Below the equilibrium price", "Above the equilibrium price", "At the equilibrium price", "At zero"], "ans": "0", "marks": 1, "topic": "Price controls", "ok": "Correct.", "fb": "A price ceiling only bites if it is below the equilibrium price; above it, it has no effect. See section 4.", "model": "Below the equilibrium price"}, {"id": "q7", "type": "text", "q": "Complete: a maximum price set below equilibrium creates a ________.", "groups": [["shortage", "excess demand"]], "marks": 1, "topic": "Price controls", "ok": "Correct: a shortage.", "fb": "At the lower price quantity demanded rises and quantity supplied falls, creating a shortage. See section 4.", "model": "Shortage.", "hint": "One key term."}, {"id": "q8", "type": "text", "q": "Complete: a minimum price set above equilibrium creates a ________.", "groups": [["surplus", "excess supply"]], "marks": 1, "topic": "Price controls", "ok": "Correct: a surplus.", "fb": "At the higher price quantity supplied rises and quantity demanded falls, creating a surplus. See section 5.", "model": "Surplus.", "hint": "One key term."}, {"id": "q9", "type": "mcq", "q": "In a buffer stock scheme, what does the agency do when the price would fall below the minimum?", "opts": ["Buys and stores the surplus", "Sells from its stock", "Raises the maximum price", "Does nothing"], "ans": "0", "marks": 1, "topic": "Buffer stocks", "ok": "Correct.", "fb": "To defend the minimum price it buys up the surplus and stores it. When the price would rise above the maximum, it sells from stock. See section 6.", "model": "Buys and stores the surplus"}, {"id": "q10", "type": "mcq", "q": "Which is a typical limitation of using indirect taxes on goods with inelastic demand?", "opts": ["Consumption barely falls", "Revenue is always zero", "Supply becomes perfectly elastic", "Prices fall"], "ans": "0", "marks": 1, "topic": "Evaluating taxes", "ok": "Correct.", "fb": "With inelastic demand the tax raises revenue but does little to reduce consumption, so it may not achieve the aim of reducing demerit goods. See 'Limits' in section 1.", "model": "Consumption barely falls"}]$q$::jsonb)
on conflict (slug) do update set title = excluded.title, pass_pct = excluded.pass_pct, questions = excluded.questions, updated_at = now();

insert into public.assessments (slug, title, pass_pct, questions) values ('as-reasons-for-intervention', $q$Reasons for Government Intervention: assessment$q$, 80, $q$[{"id": "q1", "type": "text", "q": "Complete: public goods are non-excludable and non-________.", "groups": [["rival", "rivalrous"]], "marks": 1, "topic": "Public goods", "ok": "Correct: non-rival.", "fb": "Public goods are non-excludable (nobody can be stopped using them) and non-rival (one person's use does not reduce what is left for others). See section 1.", "model": "Rival.", "hint": "One key term."}, {"id": "q2", "type": "text", "q": "Complete: people who enjoy a public good without paying are called ________ riders.", "groups": [["free"]], "marks": 1, "topic": "Public goods", "ok": "Correct: free riders.", "fb": "The free rider problem means a private firm cannot charge, so it cannot profit and will not supply the good. See section 1.", "model": "Free.", "hint": "One word."}, {"id": "q3", "type": "mcq", "q": "Why is a street light a public good?", "opts": ["Nobody can be excluded and one person's use does not reduce others' use", "It is always provided free by private firms", "Only people who pay can see it", "It is bad for health"], "ans": "0", "marks": 1, "topic": "Public goods", "ok": "Correct.", "fb": "It is non-excludable and non-rival. Both characteristics are needed. See section 1.", "model": "Nobody can be excluded and one person's use does not reduce others' use"}, {"id": "q4", "type": "mcq", "q": "In a free market, merit goods are likely to be:", "opts": ["Under-consumed", "Over-consumed", "Provided in the right amount", "Banned"], "ans": "0", "marks": 1, "topic": "Merit goods", "ok": "Correct.", "fb": "Consumers do not fully realise the benefits, so too little is consumed. Healthcare and education are the standard examples. See section 3.", "model": "Under-consumed"}, {"id": "q5", "type": "mcq", "q": "In a free market, demerit goods are likely to be:", "opts": ["Over-consumed", "Under-consumed", "Non-excludable", "Provided free"], "ans": "0", "marks": 1, "topic": "Demerit goods", "ok": "Correct.", "fb": "Consumers lack full information about the harm, so too much is consumed. Cigarettes are the standard example. See section 2.", "model": "Over-consumed"}, {"id": "q6", "type": "mcq", "q": "Which of these is a merit good?", "opts": ["Education", "Cigarettes", "Street lighting", "A luxury watch"], "ans": "0", "marks": 1, "topic": "Merit goods", "ok": "Correct.", "fb": "Education is more beneficial than consumers realise. Cigarettes are demerit, and street lighting is a public good. See sections 1 to 3.", "model": "Education"}, {"id": "q7", "type": "mcq", "q": "Why might a government set a minimum price for wheat?", "opts": ["To support farmers' incomes and food supply", "To help consumers buy it more cheaply", "To remove the need for farmers", "To cut the cost of imports to zero"], "ans": "0", "marks": 1, "topic": "Price controls", "ok": "Correct.", "fb": "Farm incomes are unpredictable because supply is uncertain, and governments want to rely less on imports of staples. See section 4.", "model": "To support farmers' incomes and food supply"}, {"id": "q8", "type": "text", "q": "Complete: market failure is an inefficient allocation of ________.", "groups": [["resources"]], "marks": 1, "topic": "Market failure", "ok": "Correct: resources.", "fb": "Market failure means the price mechanism fails to take account of all costs and benefits, so resources are allocated inefficiently. See 'The big idea'.", "model": "Resources.", "hint": "One word."}, {"id": "q9", "type": "mcq", "q": "Information failure means:", "opts": ["Consumers lack the information they need to decide well", "Firms lack information about costs", "The government has too much information", "Prices are published too late"], "ans": "0", "marks": 1, "topic": "Information failure", "ok": "Correct.", "fb": "It describes consumers lacking information, which helps explain under-consumption of merit goods and over-consumption of demerit goods. See the Learn tab.", "model": "Consumers lack the information they need to decide well"}, {"id": "q10", "type": "mcq", "q": "If a question asks WHY a government intervenes, which is the best type of point to make?", "opts": ["Explain the market failure", "Describe how a tax shifts supply", "Describe a subsidy diagram", "List the costs of a buffer stock"], "ans": "0", "marks": 1, "topic": "Exam technique", "ok": "Correct: reasons, not methods.", "fb": "Reasons relate to market failure. Taxes, subsidies and provision are methods and belong in answers about how. See the 'Reasons, not methods' box.", "model": "Explain the market failure"}]$q$::jsonb)
on conflict (slug) do update set title = excluded.title, pass_pct = excluded.pass_pct, questions = excluded.questions, updated_at = now();

insert into public.assessments (slug, title, pass_pct, questions) values ('linked-lists', $q$Linked Lists: assessment$q$, 80, $q$[{"id": "q1", "type": "mcq", "q": "What value is normally used as the null pointer at the end of a linked list?", "opts": ["0", "1", "-1", "The length of the list"], "ans": "2", "marks": 1, "topic": "Null pointer", "ok": "Correct: the last node's pointer is -1.", "fb": "The end of the list is marked by a null pointer, which the course uses as -1. Revisit section 01 (The idea).", "model": "-1"}, {"id": "q2", "type": "text", "q": "Complete: heapStartPointer holds the index of the first ________ position in the arrays.", "groups": [["free", "unused", "empty", "available"]], "marks": 1, "topic": "The heap", "ok": "Correct: the first free position.", "fb": "heapStartPointer holds the index of the first free (unused) slot, because the unused positions are kept as a linked list. See section 02 (Anatomy).", "model": "free (unused)", "hint": "One word."}, {"id": "q3", "type": "mcq", "q": "In the array implementation, how many arrays hold the list?", "opts": ["One 2D array", "Two parallel 1D arrays", "Three arrays", "A real memory address list"], "ans": "1", "marks": 1, "topic": "Anatomy", "ok": "Correct: one array for data, one for pointers.", "fb": "Exam questions use two parallel 1D arrays of the same size: one for data, one for the next-pointers. They do not use real memory addresses. See section 02.", "model": "Two parallel 1D arrays"}, {"id": "q4", "type": "num", "q": "Using the arrays shown, what is the third item in the list order? (follow the pointers from startPointer)", "ans": 27, "tol": 0, "marks": 1, "topic": "Tracing", "hint": "Enter a number.", "ok": "Correct: 16, then 19, then 27.", "fb": "Start at index 4 (16), its pointer is 1 so go to index 1 (19), whose pointer is 0, so index 0 (27). The third item is 27. Practise the trace tables in section 03.", "model": "27", "code": "index                  0    1    2    3    4\nmyLinkedList          27   19   36   42   16\nmyLinkedListPointers   2    0    3   -1    1\n\nstartPointer = 4"}, {"id": "q5", "type": "num", "q": "Using the same arrays, at which array index is the item 36 stored?", "ans": 2, "tol": 0, "marks": 1, "topic": "Anatomy", "hint": "Enter a number.", "ok": "Correct: index 2.", "fb": "The data array is [27, 19, 36, 42, 16], so 36 is at index 2. The index where an item is stored is not its position in the list order.", "model": "2", "code": "index                  0    1    2    3    4\nmyLinkedList          27   19   36   42   16\nmyLinkedListPointers   2    0    3   -1    1\n\nstartPointer = 4"}, {"id": "q6", "type": "mcq", "q": "The find function starts its search at which index?", "opts": ["Index 0", "The index in startPointer", "The last index", "heapStartPointer"], "ans": "1", "marks": 1, "topic": "Finding", "ok": "Correct.", "fb": "You do not scan from index 0. Start at startPointer and follow the chain of pointers. See section 03.", "model": "The index in startPointer", "code": "FUNCTION find(itemSearch) RETURNS INTEGER\n  itemPointer <- startPointer\n  found <- FALSE\n  WHILE (itemPointer <> -1) AND NOT found DO\n    IF myLinkedList[itemPointer] = itemSearch THEN\n      found <- TRUE\n    ELSE\n      itemPointer <- myLinkedListPointers[itemPointer]\n    ENDIF\n  ENDWHILE\n  RETURN itemPointer\nENDFUNCTION"}, {"id": "q7", "type": "text", "q": "Look at the code. What value does the function return (the value left in itemPointer) when the item is not in the list?", "groups": [["-1", "minus 1", "null pointer", "nullpointer", "null"]], "marks": 1, "topic": "Finding", "ok": "Correct.", "fb": "The search failing is the outcome, but the function returns a value: when the loop ends without finding the item, itemPointer has followed the chain to the null pointer, -1. The code that called find treats -1 as 'not found'. Trace the loop in section 03.", "model": "-1, the null pointer. The calling code reads -1 as 'not found'.", "hint": "A value, not a sentence.", "code": "FUNCTION find(itemSearch) RETURNS INTEGER\n  itemPointer <- startPointer\n  found <- FALSE\n  WHILE (itemPointer <> -1) AND NOT found DO\n    IF myLinkedList[itemPointer] = itemSearch THEN\n      found <- TRUE\n    ELSE\n      itemPointer <- myLinkedListPointers[itemPointer]\n    ENDIF\n  ENDWHILE\n  RETURN itemPointer\nENDFUNCTION"}, {"id": "q8", "type": "mcq", "q": "When inserting a new node into the middle of a sorted linked list, which of these is NOT needed?", "opts": ["Moving existing data items along the array", "Taking a free slot from the heap", "Changing the previous node's pointer", "Giving the new node a pointer to the next node"], "ans": "0", "marks": 1, "topic": "Inserting", "ok": "Correct: no data ever moves.", "fb": "The point of a linked list is that no data moves. You take a free slot, set the new node's pointer and redirect the previous node's pointer. See section 04.", "model": "Moving existing data items along the array"}, {"id": "q9", "type": "mcq", "q": "Why can inserting into a sorted linked list be quicker than inserting into a sorted array?", "opts": ["Existing items do not have to be shifted along; only pointers change", "The array has to be searched from index 0 every time", "A linked list needs no heap", "Pointers are always faster to read than data"], "ans": "0", "marks": 1, "topic": "Linked list vs array", "ok": "Correct: no data moves.", "fb": "In a sorted array every later item has to be shifted along to make room. In a linked list no data moves and only a couple of pointers are changed. See section 06 (vs. arrays).", "model": "Existing items do not have to be shifted along; only pointers change"}, {"id": "q10", "type": "num", "q": "A linked list is made from arrays of 12 elements and currently holds 5 items. How many nodes are on the heap?", "ans": 7, "tol": 0, "marks": 1, "topic": "The heap", "hint": "Enter a number.", "ok": "Correct: 12 − 5 = 7.", "fb": "Every position not in the list is on the heap (the free list). 12 − 5 = 7. See section 02.", "model": "7"}]$q$::jsonb)
on conflict (slug) do update set title = excluded.title, pass_pct = excluded.pass_pct, questions = excluded.questions, updated_at = now();
